/**
 * The Monolith: Sheet Agent Engine with Native Function Calling
 * Runtime: Google Apps Script
 */

// Initialize Custom Menu
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Architect Engine')
    .addItem('Open Renovation Agent', 'showSidebar')
    .addToUi();
}

// Inject and Display Sidebar Canvas
function showSidebar() {
  var html = HtmlService.createTemplateFromFile('Sidebar')
    .evaluate()
    .setTitle('Renovation Agent Core')
    .setWidth(400);
  SpreadsheetApp.getUi().showSidebar(html);
}

/**
 * Creates a comprehensive Renovation Tracker with dynamic scenarios and portfolio overview.
 * Fixed: Column width logic now correctly iterates through arrays.
 */

function createRenovationTracker() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();

  // Clear any existing configurations safely to avoid structural compilation errors
  var sheetsToClear = [
    "Overview & Portfolio Matrix",
    "Dimensions & Material Specs", 
    "The Baseline (No-Matter-What)", 
    "Scenario 1 - Downstairs South (Slab Cut)", 
    "Scenario 2 - Downstairs North (Stack Tap)", 
    "Scenario 3 - Upstairs U-Shape Open", 
    "Scenario 4 - Upstairs In-Kind L-Shape"
  ];

  // Cleans up sheets
  // wait for status so that the remainder of script will wait for finish
  const status = deleteSheetsByMatchingNames_(ss, sheetsToClear);

  // Theme configuration (The Monolith Design System Palette)
  var THEME = {
    headerBg: "#1C1A27",
    headerTextColor: "#FFFFFF",
    zebraBg: "#F9F9FB",
    accentBg: "#F1F0F5",
    textMuted: "#666666"
  };

  // show/hide gridlines
  const SHOW_HIDE_GRIDLINES_BOOL = false;

  // ==========================================
  // TAB 1: DIMENSIONS & MATERIAL SPECS
  // ==========================================
  var dimSheet = ss.insertSheet("Dimensions & Material Specs");

  dimSheet.setHiddenGridlines(SHOW_HIDE_GRIDLINES_BOOL);

  dimSheet.getRange("A1:E1").merge().setValue("PROPERTY SPACE DIMENSIONS & VARIABLE CALCULATORS")
    .setBackground(THEME.headerBg).setFontColor(THEME.headerTextColor).setFontWeight("bold").setFontSize(12).setHorizontalAlignment("center");

  var dimHeaders = [["Room/Zone", "Length (ft)", "Width (ft)", "Ceiling Height (ft)", "Calculated Floor Sq Ft"]];
  dimSheet.getRange("A2:E2").setValues(dimHeaders).setFontWeight("bold").setBackground(THEME.accentBg);

  var dimData = [
    ["Lower Level Living Room", 18, 14, 9.5, "=B3*C3"],
    ["Lower Level Bedroom (North)", 12, 11, 9.5, "=B4*C4"],
    ["Lower Level Bathroom", 8, 6, 9.5, "=B5*C5"],
    ["Upper Level Kitchen Space", 18, 9, 8, "=B6*C6"],
    ["Upper Level Hall Bathroom", 9, 6, 8, "=B7*C7"],
    ["Upper Level Primary Bedroom", 16, 14, 8, "=B8*C8"],
    ["Upper Level Primary Bathroom", 12, 10, 8, "=B9*C9"],
    ["Upper Level Second Bedroom (Jason Office)", 12, 11, 8, "=B10*C10"],
    ["Staircase Zone", 14, 4, 10, "=B11*C11"]
  ];
  dimSheet.getRange(3, 1, dimData.length, 5).setValues(dimData);

  var injectStartRow = 14;
  dimSheet.getRange(injectStartRow, 1, 1, 3).merge().setValue("GLOBAL MATERIAL UNIT COST ASSUMPTIONS")
    .setFontWeight("bold").setBackground(THEME.headerBg).setFontColor(THEME.headerTextColor);

  dimSheet.getRange(injectStartRow + 1, 1, 1, 3).setValues([["Material Type", "Est. Unit Cost (per Sq Ft)", "Reference Link / Notes"]]).setFontWeight("bold").setBackground(THEME.accentBg);

  var injectData = [
    ["High-End Hardwood Flooring Material", 14.50, "Upper floor and staircase premium specification"],
    ["Primary Bathroom Premium Floor Tile", 18.00, "Luxury finish porcelain or natural stone"],
    ["Lower Level Bathroom Floor Tile", 12.00, "Mid-to-high clean aesthetic specification"],
    ["Hall/Jack-and-Jill Bathroom Floor Tile", 12.00, "Upstairs bathroom floor material baseline"],
    ["Wall Tile / Backsplash Material (Average)", 15.00, "Wet walls and kitchen tile treatments"],
    ["Premium Interior Paint Paint (per Gal)", 75.00, "Low-sheen matte finish formulations"]
  ];
  dimSheet.getRange(injectStartRow + 2, 1, injectData.length, 3).setValues(injectData);
  dimSheet.getRange(injectStartRow + 2, 2, injectData.length, 1).setNumberFormat("$#,##0.00");
  dimSheet.getRange("B3:E11").setNumberFormat("#,##0.00").setHorizontalAlignment("right");

  // Fix: Setting uniform widths for the first 3 columns
  dimSheet.setColumnWidths(1, 3, 220);

  // ==========================================
  // TAB 2: THE BASELINE (NO-MATTER-WHAT)
  // ==========================================
  var baseSheet = ss.insertSheet("The Baseline (No-Matter-What)");
  baseSheet.setHiddenGridlines(SHOW_HIDE_GRIDLINES_BOOL);

  baseSheet.getRange("A1:D1").merge().setValue("THE BASELINE SCOPE: MANDATORY INFRASTRUCTURE & REQUISITES")
    .setBackground(THEME.headerBg).setFontColor(THEME.headerTextColor).setFontWeight("bold").setFontSize(12).setHorizontalAlignment("center");

  baseSheet.getRange("A2:D2").setValues([["Category", "Scope Component Item Name", "Estimated Cost", "Technical Realities & Scope Descriptions"]])
    .setFontWeight("bold").setBackground(THEME.accentBg);

  var baselineItems = [
    ["Outdoor/Drainage", "25-ft Custom French Drain Installation", 24500.00, "Excavate along rear width of house down to footing depth; layout perforated pipe wrap in fabric and clean gravel drainage bed."],
    ["Outdoor/Drainage", "Civil Engineered Bioswale Implementation", 18500.00, "Incorporate a vegetative swale with engineered clay-soil filtration layer across rear terrain to manage surface runoff."],
    ["Outdoor/Drainage", "Sub-Grade Sump Pump Infrastructure", 8500.00, "Heavy-duty basin with dual pump backup matrix feeding directly into existing outdoor floor drain via hard pipe."],
    ["Outdoor/Drainage", "Concrete Patio Demolition & Wall Removal", 12000.00, "Break out existing concrete patio slab and demolish the existing 4-inch high perimeter concrete block wall splitting patio from yard space."],
    ["Outdoor/Drainage", "Patio Surfacing Upgrade (Decking/Tile Material)", 16500.00, "Prep ground and install high durability structural framing and overlay with premium exterior material matrix."],
    ["Outdoor/Drainage", "Utility Infrastructure Extension to Retaining Walls", 6800.00, "Trench and run dedicated irrigation supply mains and low-voltage electrical conduits out to retaining walls for lighting and garden systems."],
    ["Outdoor/Drainage", "Pre-Interior Finish Landscaping & Stabilization", 14500.00, "Grade soil, establish native planting layout, and stabilize yard contours before moving interior finishes forward."],
    ["Lower Level Core", "Expanded Stackable Lower Sliding Glass Door Assembly", 22000.00, "Structural framing alteration to maximize width/height opening on living side; install premium multi-panel stackable glass system."],
    ["Lower Level Core", "Lower Level Full Bathroom Gut Remodel", "=22000 + ('Dimensions & Material Specs'!E5 * 'Dimensions & Material Specs'!B18) + ('Dimensions & Material Specs'!E5 * 2.5 * 'Dimensions & Material Specs'!B20)", "Down-to-the-studs modernization. Cost aggregates a labor baseline plus tile allocations pulled natively from Specs tab values."],
    ["Lower Level Core", "Concrete Slab Micro-Polishing & Sealing", 14500.00, "Mechanically grind concrete down to an even matte, non-reflective finish across total lower level envelope; apply commercial sealer."],
    ["Upper Level Core", "Upstairs Hall Bathroom Finish Material Suite", 11200.00, "Upfront asset purchase of bathroom finish materials (vanity, fixtures, tile allocation) used across either bathroom scenario."],
    ["Upper Level Core", "House-Wide Premium Hardwood Subfloor & Flooring", "=SUM('Dimensions & Material Specs'!E6, 'Dimensions & Material Specs'!E8, 'Dimensions & Material Specs'!E10, 'Dimensions & Material Specs'!E11) * 'Dimensions & Material Specs'!B16 + 12000", "Calculates required wood cost automatically by summing upper level layouts + stairs from Specs sheet and applying live unit variable."],
    ["HVAC System", "3-Zone Ductless Mini-Split HVAC Matrix System", 36000.00, "Decommission and extract forced-air system; route dedicated refrigerant loops for 1 lower level zone and 2 distinct upper level zones."]
  ];
  baseSheet.getRange(3, 1, baselineItems.length, 4).setValues(baselineItems);

  var baseTotalRow = 3 + baselineItems.length;
  baseSheet.getRange(baseTotalRow, 1, 1, 2).merge().setValue("TOTAL MANDATORY BASELINE INVESTMENTS").setFontWeight("bold").setHorizontalAlignment("right");
  baseSheet.getRange(baseTotalRow, 3).setValue("=SUM(C3:C" + (baseTotalRow-1) + ")").setFontWeight("bold");
  baseSheet.getRange(baseTotalRow, 1, 1, 4).setBackground(THEME.accentBg);
  baseSheet.getRange("C3:C" + baseTotalRow).setNumberFormat("$#,##0.00").setHorizontalAlignment("right");

  var altStartRow = baseTotalRow + 3;
  baseSheet.getRange(altStartRow, 1, 1, 4).merge().setValue("PLUMBING SEWER ALTERNATIVES & MAINTENANCE REFERENCES")
    .setBackground(THEME.headerBg).setFontColor(THEME.headerTextColor).setFontWeight("bold").setFontSize(11).setHorizontalAlignment("center");

  baseSheet.getRange(altStartRow + 1, 1, 1, 4).setValues([["Scope Category", "Alternative / Operational Variable Name", "Estimated Cost", "Strategic Execution Realities & Fluid Constraints"]]).setFontWeight("bold").setBackground(THEME.accentBg);

  var altData = [
    ["Sewer Alternate", "Backflow Preventer - Garage Slab Pathway (Recommended)", 3500.00, "Install mechanical one-way backwater valve under thin floating garage slab. Lower complexity/cost. Protects ground floor drains from storm backups and external debris. Note: Creates a mechanical choke point; plumber must lift flapper inside a flush garage access vault during maintenance."],
    ["Sewer Alternate", "Backflow Preventer - Main House Slab Pathway (Alternative)", 5750.00, "Excavate directly into main structural home slab. Highly complex; involves indoor finished floor demolition, extensive structural dust containment, and subsequent tile reconstruction. Highly destructive to finished interior footprint."],
    ["Sewer Operations", "Sewer Line Preventative Hydro-Jetting (Annual Contract)", 1200.00, "Ongoing operational maintenance protocol (4x/year at $300/session) to prevent grease/solids buildup. Technical Win: Utilizes the newly identified two-way sidewalk cleanout to push a dead hose back to the backyard drain and pull debris to street."]
  ];
  baseSheet.getRange(altStartRow + 2, 1, altData.length, 4).setValues(altData);
  baseSheet.getRange(altStartRow + 2, 3, altData.length, 1).setNumberFormat("$#,##0.00");

  // Fix: Iterating to set individual column widths
  [160, 340, 140, 500].forEach((w, i) => baseSheet.setColumnWidth(i + 1, w));

  // Master function to construct individual Scenario sheets
  function buildScenarioTab(tabName, specificItems) {
    var s = ss.insertSheet(tabName);
    s.setHiddenGridlines(SHOW_HIDE_GRIDLINES_BOOL);
    s.getRange("A1:D1").merge().setValue(tabName.toUpperCase() + " ANALYSIS MATRIX").setBackground(THEME.headerBg).setFontColor(THEME.headerTextColor).setFontWeight("bold").setFontSize(11).setHorizontalAlignment("center");
    s.getRange("A2:D2").setValues([["Scope Category", "Scenario Specific Item Name", "Estimated Cost", "Strategic Execution & Architecture Parameters"]]).setFontWeight("bold").setBackground(THEME.accentBg);

    s.getRange(3, 1, specificItems.length, 4).setValues(specificItems);
    var rowIdx = 3 + specificItems.length;

    s.getRange(rowIdx, 1, 1, 2).merge().setValue("Carried Core Baseline Expenses").setFontColor(THEME.textMuted).setHorizontalAlignment("right");
    s.getRange(rowIdx, 3).setValue("='The Baseline (No-Matter-What)'!C" + baseTotalRow).setFontColor(THEME.textMuted);
    rowIdx++;

    s.getRange(rowIdx, 1, 1, 2).merge().setValue("TOTAL PROJECT PATH ESTIMATION").setFontWeight("bold").setHorizontalAlignment("right");
    s.getRange(rowIdx, 3).setValue("=SUM(C3:C" + (rowIdx-1) + ")").setFontWeight("bold");
    s.getRange(rowIdx, 1, 1, 4).setBackground(THEME.accentBg);

    s.getRange("C3:C" + rowIdx).setNumberFormat("$#,##0.00").setHorizontalAlignment("right");
    s.getRange(3, 1, specificItems.length, 4).setWrap(true);

    // Fix: Iterating to set individual column widths
    [160, 340, 140, 500].forEach((w, i) => s.setColumnWidth(i + 1, w));
    return s.getSheetId();
  }

  // Define Scenarios with dynamic reactive formula chains
  // s1Data comes from constants.gs
  var gidS1 = buildScenarioTab("Scenario 1 - Downstairs South (Slab Cut)", s1Data);

  // s2Data comes from constants.gs
  var gidS2 = buildScenarioTab("Scenario 2 - Downstairs North (Stack Tap)", s2Data);

  // s3Data comes from constants.gs
  var gidS3 = buildScenarioTab("Scenario 3 - Upstairs U-Shape Open", s3Data);

  // s4Data comes from constants.gs
  var gidS4 = buildScenarioTab("Scenario 4 - Upstairs In-Kind L-Shape", s4Data);

  // ==========================================
  // TAB 0: PORTFOLIO OVERVIEW MATRIX
  // ==========================================
  var ovSheet = ss.insertSheet("Overview & Portfolio Matrix", 0);
  ovSheet.setHiddenGridlines(SHOW_HIDE_GRIDLINES_BOOL);

  ovSheet.getRange("A1:D1").merge().setValue("REMODATION STRATEGIC FORECAST & TARGET INTERFACE")
    .setBackground(THEME.headerBg).setFontColor(THEME.headerTextColor).setFontWeight("bold").setFontSize(13).setHorizontalAlignment("center");

  ovSheet.getRange("A2:D2").setValues([["Investment Focus Target", "Strategic Scope Summary Objective", "Calculated Project Cost", "Direct Workbook Sheet Link"]])
    .setFontWeight("bold").setBackground(THEME.accentBg);

var overviewMatrix = [
  [
    "Baseline: Backyard Infrastructure", 
    "25-ft French drain, engineered bioswale, sub-grade sump matrix, concrete patio demolition, and utility lines extended to retaining walls.", 
    "=SUM('The Baseline (No-Matter-What)'!C3:C9)", 
    `=HYPERLINK("#gid=${baseSheet.getSheetId()}", "View Baseline Tab")`
  ],
  [
    "Baseline: Shared Bathrooms", 
    "Downstairs bath structural gut remodel plus comprehensive material purchases for upstairs hall and primary ensuite spaces.", 
    "=SUM('The Baseline (No-Matter-What)'!C10:C11, 'The Baseline (No-Matter-What)'!C13)", 
    `=HYPERLINK("#gid=${baseSheet.getSheetId()}", "View Baseline Tab")`
  ],
  [
    "Isolate: Kitchen Upstairs In-Kind", 
    "Pure cosmetic replacement of counters and casework within the existing L-shaped upper footprint. No wall or plumbing movement.", 
    "='Scenario 4 - Upstairs In-Kind L-Shape'!C3", 
    `=HYPERLINK("#gid=${gidS4}", "Go to Scenario 4")`
  ],
  [
    "Isolate: Kitchen Upstairs U-Shape", 
    "Full open-concept 18-ft expansion. Removes non-structural wall, installs island, and shifts sink under a newly elevated counter-height window.", 
    "=SUM('Scenario 3 - Upstairs U-Shape Open'!C4:C6)", 
    `=HYPERLINK("#gid=${gidS3}", "Go to Scenario 3")`
  ],
  [
    "Isolate: Kitchen Downstairs South", 
    "Relocates kitchen to living room side. Demolishes structural wall under cantilever and trenches 6 linear feet into foundation concrete slab.", 
    "=SUM('Scenario 1 - Downstairs South (Slab Cut)'!C3:C5)", 
    `=HYPERLINK("#gid=${gidS1}", "Go to Scenario 1")`
  ],
  [
    "Isolate: Kitchen Downstairs North", 
    "Relocates kitchen to bedroom side. Avoids slab cutting by horizontal stack tap inside shared wet-wall. Shores structural wall under cantilever.", 
    "=SUM('Scenario 2 - Downstairs North (Stack Tap)'!C3:C5)", 
    `=HYPERLINK("#gid=${gidS2}", "Go to Scenario 2")`
  ],
  [
    "Total Portfolio: Whole Home Config 1", 
    "Complete baseline + Kitchen downstairs South side (Slab Cut) + Upper library/bedroom flip + Jack & Jill bathroom layout modification.", 
    "='Scenario 1 - Downstairs South (Slab Cut)'!C13", 
    `=HYPERLINK("#gid=${gidS1}", "Open Full Path 1")`
  ],
  [
    "Total Portfolio: Whole Home Config 2", 
    "Complete baseline + Kitchen downstairs North side (Stack Tap) + Upper library/bedroom flip + Jack & Jill bathroom layout modification.", 
    "='Scenario 2 - Downstairs North (Stack Tap)'!C13", 
    `=HYPERLINK("#gid=${gidS2}", "Open Full Path 2")`
  ],
  [
    "Total Portfolio: Whole Home Config 3", 
    "Complete baseline + Kitchen upstairs In-Kind + Ground floor retained as-is + Primary bathroom custom closet laundry integration.", 
    "='Scenario 4 - Upstairs In-Kind L-Shape'!C11", 
    `=HYPERLINK("#gid=${gidS4}", "Open Full Path 4")`
  ],
  [
    "Total Portfolio: Whole Home Config 4", 
    "Complete baseline + Kitchen upstairs open U-Shape + Ground floor retained as-is + Primary bathroom custom closet laundry integration.", 
    "='Scenario 3 - Upstairs U-Shape Open'!C11", 
    `=HYPERLINK("#gid=${gidS3}", "Open Full Path 3")`
  ]
];

  ovSheet.getRange(3, 1, overviewMatrix.length, 4).setValues(overviewMatrix);
  ovSheet.getRange("C3:C" + (3 + overviewMatrix.length - 1)).setNumberFormat("$#,##0.00").setHorizontalAlignment("right");
  ovSheet.getRange("D3:D" + (3 + overviewMatrix.length - 1)).setHorizontalAlignment("center").setFontWeight("bold");
  ovSheet.getRange(3, 1, overviewMatrix.length, 4).setWrap(true);

  // Fix: Iterating to set individual column widths
  [220, 380, 160, 180].forEach((w, i) => ovSheet.setColumnWidth(i + 1, w));

  ss.setActiveSheet(ovSheet);
}

/**
 * Main Orchestration Loop for the Agent.
 * Recursively resolves function calls from the LLM engine.
 */
function handleAgentChat(userMessage, clientHistoryJSON) {
  var scriptProperties = PropertiesService.getScriptProperties();

  // Configuration Fallbacks - Replace via File > Project Settings > Script Properties or directly below
  var apiKey = scriptProperties.getProperty('API_KEY') || "YOUR_API_KEY_HERE";
  var gatewayUrl = scriptProperties.getProperty('CF_GATEWAY_URL') || "https://api.openai.com/v1/chat/completions"; 
  // If using Cloudflare AI Gateway, set URL to: https://gateway.ai.cloudflare.com/v1/{account_id}/{gateway_name}/openai/chat/completions

  var messages = [];

  // Set System Context anchored in the 4-Scenario Renovation Matrix
  messages.push({
    role: "system",
    content: "You are the Colby Renovation Agent, an elite automated systems engineer managing a high-performance home remodel project. " +
             "You have absolute programmatic authority to read, write, update, and clear cells across this spreadsheet using your tools. " +
             "Always verify sheet names before writing data. Be precise, concise, and report actions truthfully."
  });

  // Re-hydrate conversation history from client state
  if (clientHistoryJSON) {
    var history = JSON.parse(clientHistoryJSON);
    messages = messages.concat(history);
  }

  // Append new user intent
  messages.push({ role: "user", content: userMessage });

  // Define tools schema matching the Spreadsheet capability profile
  var tools = [
    {
      type: "function",
      function: {
        name: "getAvailableSheets",
        description: "Retrieves an array of all sheet tab names currently present in the active workbook document.",
        parameters: { type: "object", properties: {} }
      }
    },
    {
      type: "function",
      function: {
        name: "readSheetData",
        description: "Reads cell matrix data from a targeted sheet tab and specific range identifier.",
        parameters: {
          type: "object",
          properties: {
            sheetName: { type: "string", description: "The name of the tab to read from." },
            range: { type: "string", description: "Standard A1 notation range (e.g., 'A1:D10' or 'A:C')." }
          },
          required: ["sheetName", "range"]
        }
      }
    },
    {
      type: "function",
      function: {
        name: "updateSheetCell",
        description: "Overwrites or updates a single specific cell coordinates coordinates with a precise new scalar value or programmatic formula.",
        parameters: {
          type: "object",
          properties: {
            sheetName: { type: "string", description: "The name of the target sheet tab." },
            cell: { type: "string", description: "Single cell coordinate in A1 notation (e.g., 'C5')." },
            value: { type: "string", description: "The raw data, string text, or formula string to inject." }
          },
          required: ["sheetName", "cell", "value"]
        }
      }
    },
    {
      type: "function",
      function: {
        name: "appendRowToSheet",
        description: "Appends a new line item row of data to the very bottom row of a designated sheet tab layout.",
        parameters: {
          type: "object",
          properties: {
            sheetName: { type: "string", description: "The target sheet tab name." },
            rowDataArray: { 
              type: "array", 
              items: { type: "string" }, 
              description: "An ordered array of strings/numbers representing columns to write (e.g. ['Category', 'Item', '1500', 'Notes'])." 
            }
          },
          required: ["sheetName", "rowDataArray"]
        }
      }
    },
    {
      type: "function",
      function: {
        name: "clearSheetRange",
        description: "Clears contents from a specific range inside a designated sheet tab.",
        parameters: {
          type: "object",
          properties: {
            sheetName: { type: "string", description: "The name of the sheet tab." },
            range: { type: "string", description: "A1 notation range to clear completely." }
          },
          required: ["sheetName", "range"]
        }
      }
    }
  ];

  var maxRecursionLoops = 5;
  var currentIteration = 0;
  var agentExecutionLogs = [];

  while (currentIteration < maxRecursionLoops) {
    currentIteration++;

    var payload = {
      model: "google-ai-studio/gemini-3.1-flash", // Can be targeted to specific models upstream via Cloudflare AI Gateway fallbacks
      messages: messages,
      tools: tools,
      tool_choice: "auto",
      temperature: 0.2
    };

    var options = {
      method: "post",
      contentType: "application/json",
      headers: { "cf-aig-authorization": "Bearer " + apiKey },
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    var response = UrlFetchApp.fetch(gatewayUrl, options);
    var responseCode = response.getResponseCode();
    var responseText = response.getContentText();

    if (responseCode !== 200) {
      throw new Error("Execution Loop Interrupted. Code: " + responseCode + " | Detail: " + responseText);
    }

    var result = JSON.parse(responseText);
    var choice = result.choices[0];
    var responseMessage = choice.message;

    // Append model response back to internal loop context arrays
    messages.push(responseMessage);

    if (responseMessage.tool_calls && responseMessage.tool_calls.length > 0) {
      // Execute each requested tool in parallel/sequence
      for (var i = 0; i < responseMessage.tool_calls.length; i++) {
        var toolCall = responseMessage.tool_calls[i];
        var functionName = toolCall.function.name;
        var functionArgs = JSON.parse(toolCall.function.arguments);

        agentExecutionLogs.push("Executing: " + functionName + " with parameters " + toolCall.function.arguments);

        var toolExecutionResult = "";
        try {
          toolExecutionResult = executeLocalSpreadsheetTool(functionName, functionArgs);
        } catch (err) {
          toolExecutionResult = "Execution Error: " + err.toString();
        }

        // Return tool output back into messages payload matrix
        messages.push({
          tool_call_id: toolCall.id,
          role: "tool",
          name: functionName,
          content: toolExecutionResult
        });
      }
      // Continue loop iteration to feed data back to model for next thinking step
    } else {
      // No further tool calls requested, agent has finished formulating final summary statement
      return JSON.stringify({
        finalResponse: responseMessage.content,
        updatedHistory: messages.slice(1), // Omit the long system prompt to optimize storage footprint
        executionLogs: agentExecutionLogs
      });
    }
  }

  return JSON.stringify({
    finalResponse: "Error: Maximum recursive agent safety loop depth exceeded without resolution.",
    updatedHistory: messages.slice(1),
    executionLogs: agentExecutionLogs
  });
}

/**
 * Tool Execution Switch Matrix
 * Direct structural bindings to Google Apps Script Spreadsheet API
 */
function executeLocalSpreadsheetTool(name, args) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();

  switch (name) {
    case "getAvailableSheets":
      var sheets = ss.getSheets();
      var names = sheets.map(function(s) { return s.getName(); });
      return JSON.stringify({ existingTabs: names });

    case "readSheetData":
      var targetSheet = ss.getSheetByName(args.sheetName);
      if (!targetSheet) return "Error: Tab designated as '" + args.sheetName + "' does not exist.";
      var values = targetSheet.getRange(args.range).getValues();
      return JSON.stringify({ rangeData: values });

    case "updateSheetCell":
      var targetSheet = ss.getSheetByName(args.sheetName);
      if (!targetSheet) return "Error: Tab designated as '" + args.sheetName + "' does not exist.";
      var range = targetSheet.getRange(args.cell);

      if (args.value.toString().startsWith("=")) {
        range.setFormula(args.value);
      } else {
        range.setValue(args.value);
      }
      SpreadsheetApp.flush(); // Enforce layout calculation immediately
      return "Success: Written value into coordinates " + args.cell + " on tab " + args.sheetName;

    case "appendRowToSheet":
      var targetSheet = ss.getSheetByName(args.sheetName);
      if (!targetSheet) return "Error: Tab designated as '" + args.sheetName + "' does not exist.";
      targetSheet.appendRow(args.rowDataArray);
      SpreadsheetApp.flush();
      return "Success: Row appended to bottom of " + args.sheetName;

    case "clearSheetRange":
      var targetSheet = ss.getSheetByName(args.sheetName);
      if (!targetSheet) return "Error: Tab designated as '" + args.sheetName + "' does not exist.";
      targetSheet.getRange(args.range).clearContent();
      SpreadsheetApp.flush();
      return "Success: Contents stripped out from range " + args.range + " on tab " + args.sheetName;

    default:
      throw new Error("Tool function identifier mapping mismatch exception.");
  }
}

/**
 * Deletes sheets from a spreadsheet by iterating through existing sheets 
 * and checking if their names match any in the provided target array.
 *
 * @param {GoogleAppsScript.Spreadsheet.Spreadsheet} ss - The live spreadsheet instance.
 * @param {string[]} sheetsToClear - Array of sheet names targeted for deletion.
 */
function deleteSheetsByMatchingNames_(ss, sheetsToClear) {
  // Guard clause to ensure valid inputs
  if (!ss || !Array.isArray(sheetsToClear) || sheetsToClear.length === 0) {
    console.log("Invalid spreadsheet object or empty sheetsToClear array provided.");
    return false;
  }

  // Retrieve a snapshot array of all existing sheets in the spreadsheet
  var existingSheets = ss.getSheets();

  existingSheets.forEach(function(sheet) {
    var sheetName = sheet.getName();

    // Check if the current sheet's name matches any name in the targeting array
    if (sheetsToClear.includes(sheetName)) {
      try {
        ss.deleteSheet(sheet);
        console.log(`Successfully deleted sheet: "${sheetName}"`);
      } catch (error) {
        // This handles cases like trying to delete the last remaining visible sheet in the workbook
        console.log(`Error when trying to delete sheet "${sheetName}". Error: ${error.toString()}`);
      }
    }
  });
  return true;
}

/**
 * Exports the current Google Apps Script project configuration and source files
 * as a unified JSON backup file in Google Drive, then outputs the file URL.
 * * @return {string} The public/private URL of the generated JSON file on Drive.
 */
function downloadCurrentScriptToDriveAsJson() {
  try {
    // Trick the Apps Script compiler into implicitly requesting the complete 
    // Google Drive OAuth scope (https://www.googleapis.com/auth/drive) for this project token.
    var scopeTrigger = DriveApp.getRootFolder();

    // Acquire the unique script ID of the currently executing project
    var scriptId = ScriptApp.getScriptId();
    console.log("Initializing backup sequence for Script ID: " + scriptId);

    // Step 1: Retrieve the human-readable script name from Drive metadata
    var metadataUrl = "https://www.googleapis.com/drive/v3/files/" + scriptId;
    var metadataResponse = UrlFetchApp.fetch(metadataUrl, {
      method: "get",
      headers: {
        "Authorization": "Bearer " + ScriptApp.getOAuthToken()
      },
      muteHttpExceptions: true
    });

    var scriptName = "Untitled_Script";
    if (metadataResponse.getResponseCode() === 200) {
      var metadata = JSON.parse(metadataResponse.getContentText());
      if (metadata.name) {
        // Sanitize name for a clean operating system filename
        scriptName = metadata.name.replace(/[^a-zA-Z0-9_\-]/g, "_");
      }
    } else {
      console.log("Metadata retrieval fallback active. Code: " + metadataResponse.getResponseCode());
    }

    // Step 2: Query the Drive API export route using the specialized Apps Script JSON MIME type
    var exportUrl = "https://www.googleapis.com/drive/v3/files/" + scriptId + "/export?mimeType=application/vnd.google-apps.script%2Bjson";

    var exportResponse = UrlFetchApp.fetch(exportUrl, {
      method: "get",
      headers: {
        "Authorization": "Bearer " + ScriptApp.getOAuthToken()
      },
      muteHttpExceptions: true
    });

    if (exportResponse.getResponseCode() !== 200) {
      throw new Error("Drive API Export failed with status code " + exportResponse.getResponseCode() + ": " + exportResponse.getContentText());
    }

    var rawJsonPayload = exportResponse.getContentText();

    // Step 3: Format file name with a precise system timestamp
    var timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd_HHmmss");
    var finalFileName = scriptName + "_ProjectBackup_" + timestamp + ".json";

    // Step 4: Stream the JSON text payload directly into a new Drive File
    var createdFile = DriveApp.createFile(finalFileName, rawJsonPayload, MimeType.PLAIN_TEXT);
    var generatedUrl = createdFile.getUrl();

    // Output the resulting asset link explicitly to the console log terminal
    console.log("==========================================================================================");
    console.log("SUCCESS: Script compilation fully downloaded and committed to Drive storage.");
    console.log("Saved File Name : " + finalFileName);
    console.log("Drive Access URL: " + generatedUrl);
    console.log("==========================================================================================");

    return generatedUrl;

  } catch (error) {
    console.log("CRITICAL FAILURE in downloadCurrentScriptToDriveAsJson: " + error.toString());
    throw error;
  }
}
